import csv, json, math
bands = {}
with open("data.csv") as f:
    for row in csv.DictReader(f):
        b = row["band"]
        v = float(row["mean_value"])
        bands.setdefault(b, []).append(v)
pred = {b: sum(vals)/len(vals) for b, vals in bands.items()}
answer = {"prediction": pred, "rationale": "Forecast uses each band's historical mean value as next month estimate."}
json.dump(answer, open("answer.json","w"))
print(json.dumps(answer, indent=2))
